// #ecc64c3ab613e945688cddaf — билет загрузки части записи звонка передаётся в заголовке x-upload-ticket,
// а не в URL; загрузка частей работает. Кейс REC-001.
// МЕДЛЕННЫЙ (~3–5 мин) и НЕ prod-safe: создаёт кандидата «QA-AUTO-REC-…» (ссылка без отправки письма/SMS),
// тратит его официальный звонок и вызовы AI. Кандидат не удаляется (правило проекта — только с «да»).
// Звонок — в отдельном Chrome с фальшивым микрофоном (.qa/audio/g4/A.wav). Пропустить в регрессе:
//   npm test -- --grep-invert @slow
import { chromium, Page, Response } from '@playwright/test';
import * as path from 'path';
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';

const WAV = path.resolve(__dirname, '../../../audio/g4/A.wav');
const SIMULATION = process.env.QA_CALL_SIMULATION || 'מערכות סולאריות'; // активная симуляция бизнеса testim
const MIN_PARTS = 6; // частей записи до завершения звонка (часть ≈ каждые 5 с)

/** business: новый кандидат со ссылкой (канал link_only — ничего не отправляется). Возвращает ссылку /c/… */
async function createCandidateLink(page: Page, name: string): Promise<string> {
  await page.goto('/candidates/new');
  const sim = page.locator('#candidate-simulation_id');
  await expect(sim).toBeVisible();
  const opts = await sim.locator('option').evaluateAll((o) => (o as HTMLOptionElement[]).map((x) => ({ v: x.value, t: x.textContent || '' })));
  const target = opts.filter((o) => o.v && o.t.includes(SIMULATION));
  expect(target, `нет активной симуляции «${SIMULATION}» (QA_CALL_SIMULATION)`).toHaveLength(1);
  const managers = await page.locator('#candidate-assigned_manager_id option').evaluateAll((o) =>
    (o as HTMLOptionElement[]).map((x) => ({ v: x.value, t: x.textContent || '' })).filter((x) => x.v),
  );
  await page.locator('#candidate-full_name').fill(name);
  await page.locator('#candidate-phone').fill('05000094' + String(10 + Math.floor(Math.random() * 90)));
  await page.locator('#candidate-role_title').fill('QA-AUTO נציג');
  await page.locator('#candidate-assigned_manager_id').selectOption((managers.find((m) => m.t.includes('fdfdf')) || managers[0]).v);
  await sim.selectOption(target[0].v);
  await page.locator('input[name=send_channel][value=link_only]').check();
  await page.getByRole('button', { name: /יצירת קישור/ }).click();
  let link = '';
  await expect
    .poll(async () => {
      link = ((await page.content()).match(/https?:\/\/[^"'<\s]*\/c\/[A-Za-z0-9_\-]+/) || [''])[0];
      return link;
    }, { message: 'ссылка кандидата /c/… не появилась', timeout: 30_000 })
    .not.toBe('');
  return link;
}

/** Кнопка по тексту: дождаться и нажать. */
async function tap(page: Page, name: string | RegExp, timeout = 30_000) {
  const b = page.getByRole('button', { name }).first();
  await expect(b).toBeVisible({ timeout });
  await b.click();
}

type Ticket = { uploadUrl: string; hasHeader: boolean };
type Put = { url: string; status: number; hasHeader: boolean };

test.describe('Запись звонка — билет загрузки в заголовке (#ecc64c3ab613e945688cddaf) @call', () => {
  test('recording-upload-url без query и с upload_headers.x-upload-ticket; каждый PUT части без «ticket=» в URL, с заголовком, 2xx @desktop @data @slow #ecc64c3ab613e945688cddaf', async ({ asUser }) => {
    test.setTimeout(10 * 60_000);
    const business = await asUser('business');
    const name = `QA-AUTO-REC-${runStamp()}`;
    const link = await createCandidateLink(business, name);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}» (официальный звонок использован), не удаляется` });

    const browser = await chromium.launch({
      channel: process.env.QA_CALL_CHANNEL || 'chrome',
      args: [
        '--use-fake-ui-for-media-stream',
        '--use-fake-device-for-media-stream',
        `--use-file-for-fake-audio-capture=${WAV}`,
        '--autoplay-policy=no-user-gesture-required',
      ],
    });
    try {
      const ctx = await browser.newContext({
        locale: 'he-IL',
        viewport: { width: 390, height: 844 },
        isMobile: true,
        hasTouch: true,
        permissions: ['microphone'],
      });
      const page = await ctx.newPage();

      const tickets: Ticket[] = [];
      const puts: Put[] = [];
      const errors: string[] = [];
      page.on('response', async (r: Response) => {
        if (!r.url().includes('recording-upload-url')) return;
        const method = r.request().method();
        try {
          if (method === 'POST') {
            const body = (await r.json()) as { upload_url?: string; upload_headers?: Record<string, string> };
            tickets.push({ uploadUrl: body.upload_url || '', hasHeader: !!body.upload_headers?.['x-upload-ticket'] });
          } else if (method === 'PUT') {
            const h = await r.request().allHeaders();
            puts.push({ url: r.url(), status: r.status(), hasHeader: !!h['x-upload-ticket'] });
          }
        } catch (e) {
          errors.push(`${method} ${r.status()}: ${String(e).slice(0, 120)}`);
        }
      });

      // Кандидат: вступление → техническая проверка → пропуск тренировки → официальный звонок.
      await page.goto(link);
      await tap(page, 'בוא נתחיל');
      await tap(page, 'לראות פרטי לקוח');
      await tap(page, 'להמשיך');
      await page.getByRole('checkbox').first().check();
      await tap(page, /^להתחיל$/);
      await tap(page, 'להתחיל בדיקה');
      await tap(page, 'כן, שומעים טוב', 60_000);
      await tap(page, 'להמשיך לתרגול');
      await tap(page, 'לדלג ישר לשיחה הרשמית');
      await page.getByRole('checkbox', { name: /ניסיון חד-פעמי/ }).check();
      await tap(page, 'מוכן, מתחילים');

      // Ждём несколько загруженных частей, затем завершаем звонок.
      await expect
        .poll(() => puts.filter((p) => p.status < 300).length, { message: `меньше ${MIN_PARTS} частей записи загружено`, timeout: 4 * 60_000 })
        .toBeGreaterThanOrEqual(MIN_PARTS);
      const done = page.getByText('הסימולציה הושלמה');
      if (!(await done.isVisible())) {
        await tap(page, 'לסיים שיחה');
        await tap(page, 'לאשר סיום שיחה');
      }
      await expect(done).toBeVisible({ timeout: 60_000 });
      // Последние части догружаются после завершения: ждём ответы на все выданные билеты.
      await expect.poll(() => puts.length, { timeout: 60_000 }).toBeGreaterThanOrEqual(tickets.length);

      test.info().annotations.push({ type: 'parts', description: `билетов ${tickets.length}, PUT ${puts.length}` });
      expect(errors).toEqual([]);
      // Источник: AC — «כרטיס העלאת חלק הקלטה אינו מופיע בכתובת הבקשה, וההעלאה עובדת כמו קודם».
      expect(tickets.length).toBeGreaterThanOrEqual(MIN_PARTS);
      expect(tickets.filter((t) => !t.uploadUrl || t.uploadUrl.includes('?') || /ticket=/i.test(t.uploadUrl)).length, 'upload_url с query/ticket').toBe(0);
      expect(tickets.filter((t) => !t.hasHeader).length, 'нет upload_headers.x-upload-ticket').toBe(0);
      expect(puts.filter((p) => /[?&]ticket=/i.test(p.url)).length, 'PUT с ticket= в URL').toBe(0);
      expect(puts.filter((p) => !p.hasHeader).length, 'PUT без заголовка x-upload-ticket').toBe(0);
      expect(puts.filter((p) => p.status < 200 || p.status >= 300).map((p) => p.status), 'PUT не 2xx').toEqual([]);
    } finally {
      await browser.close();
    }
  });
});
